using System;
using Cyclomania;
using UnityEngine;
public static class MissionValidation
{
    static int count;
    static void Check(bool ok,string message) {if(!ok)throw new Exception(message);count++;Debug.Log("PASS: "+message);}
    static MissionDefinition Definition(ObjectiveKind kind,float target=10,float limit=60)=>new MissionDefinition {Id="test",Title="Test",TimeLimit=limit,Objectives=new[]{new MissionObjective {kind=kind,target=target,point=Vector3.forward*20,speedKmh=20}}};
    static MissionSample Sample(float speed=36)=>new MissionSample {Position=Vector3.zero,Grounded=true,SpeedKmh=speed};
    public static void Run()
    {
        var session=new MissionSession();
        Check(!session.Start(null),"missing mission definition rejected");
        var bad=Definition(ObjectiveKind.Distance);bad.Objectives[0].target=float.NaN;Check(!session.Start(bad),"nonfinite objective rejected");
        var d=Definition(ObjectiveKind.Distance,20);Check(session.Start(d) && !session.Start(d),"cannot replace an active attempt");
        d.Objectives[0].target=999;Check(session.Objective.target==20,"attempt snapshots objective definition");
        session.Tick(Sample(),2,true);Check(session.Countdown==3 && session.Elapsed==0,"pause freezes countdown");
        session.Tick(Sample(),2,false);Check(session.State==MissionState.Countdown && session.Progress==0,"countdown does not collect objective progress");
        session.Tick(Sample(),2,false);Check(session.State==MissionState.Running && session.Elapsed==1 && session.Progress==10,"countdown remainder becomes timed riding");
        int completed=0;session.Completed+=()=>completed++;
        session.Tick(Sample(),1,false);session.Tick(Sample(),50,false);session.BankScore(999);
        Check(session.State==MissionState.Completed && completed==1 && session.Elapsed==2,"completion and reward event fire once");
        session.Clear();Check(session.State==MissionState.Idle && session.Definition==null,"dismiss restores idle state");
        session.Start(Definition(ObjectiveKind.Distance,100,1));session.Tick(Sample(),3,false);session.Tick(Sample(),2,false);
        Check(session.State==MissionState.Failed && session.Elapsed==1,"time limit fails unfinished mission without overtime");
        session.Start(Definition(ObjectiveKind.WheelieHold,10));session.Tick(Sample(),3,false);
        var wheelie=Sample();wheelie.Wheelie=true;session.Tick(wheelie,6,false);session.Tick(Sample(),.02f,false);
        Check(session.Progress==0,"wheelie must be continuous");session.Tick(wheelie,10,false);Check(session.State==MissionState.Completed,"continuous wheelie satisfies objective");
        session.Start(Definition(ObjectiveKind.SpeedHold,5));session.Tick(Sample(),3,false);session.Tick(Sample(),3,false);session.Tick(Sample(19),.1f,false);
        Check(session.Progress==0,"dropping below speed threshold resets hold");session.Tick(Sample(),5,false);Check(session.State==MissionState.Completed,"continuous speed hold completes");
        var route=Definition(ObjectiveKind.ReachPoint,1);route.Objectives=new[]{new MissionObjective {kind=ObjectiveKind.ReachPoint,point=Vector3.forward*20},new MissionObjective {kind=ObjectiveKind.ReachPoint,point=Vector3.forward*40}};
        session.Start(route);session.Tick(Sample(),3,false);var at=Sample();at.Position=Vector3.forward*40;session.Tick(at,.1f,false);
        Check(session.ObjectiveIndex==0,"out-of-order checkpoints do not count");at.Position=Vector3.forward*20;at.Grounded=false;session.Tick(at,.1f,false);Check(session.ObjectiveIndex==0,"flying above checkpoint does not count");
        at.Grounded=true;session.Tick(at,.1f,false);Check(session.ObjectiveIndex==1,"first checkpoint advances ordered route");at.Position=Vector3.forward*40;session.Tick(at,.1f,false);Check(session.State==MissionState.Completed,"ordered route finishes at final checkpoint");
        session.Start(Definition(ObjectiveKind.BankedScore,100));session.BankScore(100);Check(session.Progress==0,"countdown cannot earn score objective");session.Tick(Sample(),3,false);session.BankScore(40);session.BankScore(60);Check(session.State==MissionState.Completed,"banked scores accumulate toward target");
        session.Start(Definition(ObjectiveKind.Distance));session.Fail("Crash");session.Tick(Sample(),100,false);Check(session.State==MissionState.Failed && session.Result=="Crash","failed attempt cannot resume collecting progress");
        session.Start(Definition(ObjectiveKind.Distance));session.Abandon();Check(session.State==MissionState.Abandoned,"abandon terminates countdown");
        var career=new MissionCareer();Check(career.Record(0,1,20,100) && !career.Record(0,1,20,100) && career.points==100,"career grants each completed tier reward once");
        Check(!career.Record(0,3,1,500) && career.NextLevel(0)==2,"career cannot skip tiers");
        var saved=MissionCareer.FromJson(career.ToJson());Check(saved.completed[0]==1 && saved.bestSeconds[0]==20 && saved.points==100,"career save round trip retains progression results and points");
        var corrupt=MissionCareer.FromJson("{\"version\":1,\"completed\":[-2,999],\"points\":-4}");Check(corrupt.completed.Length==MissionCatalog.Count && corrupt.completed[0]==0 && corrupt.completed[1]==100 && corrupt.points==0,"invalid career data normalized");
        Check(MissionCareer.FromJson("broken").points==0,"corrupt career save recovers defaults");
        Check(MissionCatalog.Create(2,1).Objectives[0].target==10 && MissionCatalog.Create(2,2).Objectives[0].target==35,"repeat wheelie difficulty increases from ten to thirty-five seconds");
        Check(MissionCatalog.Create(0,2).Objectives[0].target>MissionCatalog.Create(0,1).Objectives[0].target && MissionCatalog.Create(1,2).TimeLimit<MissionCatalog.Create(1,1).TimeLimit,"distance and route contracts scale difficulty");
        var oldSave=MissionCareer.FromJson("{\"version\":1,\"points\":250,\"completed\":[2,1,0],\"bestSeconds\":[20,30,0]}");
        Check(oldSave.completed.Length==MissionCatalog.Count && oldSave.completed[0]==2 && oldSave.completed[1]==1 && oldSave.completed[3]==0 && oldSave.points==250,"tutorial catalog expansion preserves prior career progress");
        var tutorial=MissionCatalog.Create(MissionCatalog.TutorialIndex,1);session.Start(tutorial);session.Tick(Sample(),3,false);
        var learner=Sample(10);session.Tick(learner,3,false);Check(session.Progress==0,"coasting does not pass pedal lesson");
        learner.Acceleration=1;learner.Grounded=false;session.Tick(learner,3,false);Check(session.Progress==0,"airborne pedaling does not pass lesson");
        learner.Grounded=true;session.Tick(learner,2,false);Check(session.ObjectiveIndex==1,"grounded pedal hold advances to braking");
        learner.SpeedKmh=0;learner.Acceleration=-1;session.Tick(learner,2,false);Check(session.ObjectiveIndex==1 && !session.BrakeArmed,"stationary brake pressing cannot bypass moving stop lesson");
        learner.SpeedKmh=7;session.Tick(learner,.1f,false);Check(session.BrakeArmed,"braking lesson arms after reaching required speed");
        learner.SpeedKmh=0;learner.Acceleration=0;session.Tick(learner,2,false);Check(session.ObjectiveIndex==1,"coasting to rest does not prove brake input");
        learner.Acceleration=-1;session.Tick(learner,1,false);Check(session.ObjectiveIndex==2 && !session.BrakeArmed,"braking to stable stop advances and clears stop state");
        learner.SpeedKmh=6;learner.Steering=1;learner.YawDelta=25;session.Tick(learner,.1f,false);Check(session.Progress==0,"right turn does not satisfy left lesson");
        learner.Steering=-1;learner.YawDelta=0;session.Tick(learner,2,false);Check(session.Progress==0,"steering input without physical turning earns no progress");
        learner.YawDelta=-10;learner.Grounded=false;session.Tick(learner,.1f,false);Check(session.Progress==0,"airborne rotation does not satisfy grounded steering");
        learner.Grounded=true;session.Tick(learner,.1f,false);Check(session.Progress==10,"actual left rotation advances left lesson");
        learner.YawDelta=5;session.Tick(learner,.1f,false);Check(session.Progress==5,"opposite physical rotation removes steering progress");
        learner.YawDelta=-15;session.Tick(learner,.1f,false);Check(session.ObjectiveIndex==3,"left turn unlocks right lesson");
        learner.Steering=1;learner.YawDelta=20;session.Tick(learner,.1f,false);Check(session.ObjectiveIndex==4,"right turn unlocks final stop");
        learner.SpeedKmh=7;session.Tick(learner,.1f,false);learner.SpeedKmh=0;learner.Acceleration=-1;session.Tick(learner,1,false);
        Check(session.State==MissionState.Completed,"all five riding basics steps complete tutorial");
        var harder=MissionCatalog.Create(MissionCatalog.TutorialIndex,2);
        Check(harder.Objectives[0].target>tutorial.Objectives[0].target && harder.Objectives[2].target>tutorial.Objectives[2].target && harder.TimeLimit<tutorial.TimeLimit,"tutorial repeats with longer holds larger turns and tighter time");
        var previousCareer=MissionCareer.FromJson("{\"version\":1,\"points\":450,\"completed\":[2,1,0,1],\"bestSeconds\":[20,30,0,40]}");
        Check(previousCareer.completed.Length==MissionCatalog.Count && previousCareer.completed[3]==1 && previousCareer.completed[4]==0 && previousCareer.points==450,"delivery catalog expansion preserves tutorial and earlier progress");
        var delivery=MissionCatalog.Create(MissionCatalog.DeliveryIndex,1);
        Check(delivery.TimeLimit==180 && delivery.Objectives.Length==2 && Vector3.Distance(delivery.Objectives[0].point,delivery.Objectives[1].point)==140,"first pizza delivery has three minute limit and 140 meter route");
        session.Start(delivery);var courier=Sample(0);courier.Position=delivery.Objectives[0].point;
        session.Tick(courier,2,false);Check(!session.CarryingPackage && session.Progress==0,"countdown cannot collect package");session.Tick(courier,1,false);
        courier.Position=delivery.Objectives[1].point;session.Tick(courier,3,false);Check(session.ObjectiveIndex==0 && !session.CarryingPackage,"destination visit before pickup earns nothing");
        courier.Position=delivery.Objectives[0].point;courier.SpeedKmh=8;session.Tick(courier,3,false);Check(session.Progress==0,"riding through pickup too fast does not collect pizza");
        courier.SpeedKmh=0;courier.Grounded=false;session.Tick(courier,3,false);Check(session.Progress==0,"airborne pickup is rejected");
        courier.Grounded=true;session.Tick(courier,1,false);courier.Position+=Vector3.right*10;session.Tick(courier,.1f,false);Check(session.Progress==0,"leaving pickup resets handover hold");
        courier.Position=delivery.Objectives[0].point;session.Tick(courier,1,false);float time=session.Elapsed;session.Tick(courier,10,true);Check(session.Progress==1 && session.Elapsed==time,"pause freezes pickup hold and delivery timer");
        session.Tick(courier,1,false);Check(session.CarryingPackage && session.ObjectiveIndex==1,"completed pickup puts package on board");
        session.Tick(courier,3,false);Check(session.CarryingPackage && session.Progress==0,"remaining at pickup cannot complete delivery");
        courier.Position=delivery.Objectives[1].point;courier.SpeedKmh=3;session.Tick(courier,3,false);Check(session.Progress==0,"delivery requires a slow stop");
        courier.SpeedKmh=0;session.Tick(courier,2,false);Check(session.State==MissionState.Completed && !session.CarryingPackage,"destination handover completes delivery and removes cargo");
        var deliveryCareer=new MissionCareer();Check(deliveryCareer.Record(4,1,session.Elapsed,delivery.Reward) && !deliveryCareer.Record(4,1,session.Elapsed,delivery.Reward) && deliveryCareer.points==150,"delivery reward granted once per tier");
        session.Start(delivery);session.Tick(Sample(),3,false);courier.Position=delivery.Objectives[0].point;session.Tick(courier,2,false);session.Fail("Crash");Check(!session.CarryingPackage && session.State==MissionState.Failed,"failure discards carried package");
        session.Start(delivery);Check(!session.CarryingPackage && session.ObjectiveIndex==0,"retry begins with a fresh pickup");session.Tick(Sample(),3,false);session.Tick(courier,2,false);session.Abandon();Check(!session.CarryingPackage,"abandon removes delivery cargo");
        session.Start(delivery);session.Tick(Sample(),3,false);session.Tick(courier,2,false);session.Tick(courier,180,false);Check(session.State==MissionState.Failed && !session.CarryingPackage,"deadline failure removes cargo without delivery");
        var invalidDelivery=MissionCatalog.Create(4,1);invalidDelivery.Objectives=new[]{invalidDelivery.Objectives[1]};Check(!session.Start(invalidDelivery),"dropoff without pickup is not a valid mission");
        invalidDelivery=MissionCatalog.Create(4,1);invalidDelivery.Objectives=new[]{invalidDelivery.Objectives[0]};Check(!session.Start(invalidDelivery),"pickup without destination is not a valid mission");
        var delivery2=MissionCatalog.Create(4,2);Check(delivery2.TimeLimit<delivery.TimeLimit && delivery2.Objectives[1].point.z>delivery.Objectives[1].point.z && delivery2.Objectives[0].radius<delivery.Objectives[0].radius && delivery2.Objectives[0].target>delivery.Objectives[0].target,"delivery repeats grow route and tighten time and stopping precision");
        var deliveryMax=MissionCatalog.Create(4,100);Check(deliveryMax.Objectives[1].point.z<=420 && deliveryMax.Objectives[0].radius>=3 && deliveryMax.TimeLimit>=100,"upper delivery tiers stay within highway and bounded tuning");
        var fiveSave=MissionCareer.FromJson("{\"version\":1,\"points\":600,\"completed\":[2,1,0,1,1],\"bestSeconds\":[20,30,0,40,25]}");
        Check(fiveSave.completed.Length==MissionCatalog.Count && fiveSave.completed[4]==1 && fiveSave.completed[5]==0 && fiveSave.points==600,"speed trial append preserves delivery and earlier career data");
        var trial=MissionCatalog.Create(MissionCatalog.SpeedTrialIndex,1);
        Check(trial.Objectives[1].speedKmh==18 && trial.Objectives[1].target==10 && trial.Objectives[1].useZone,"first speed trial targets eighteen kmh for ten seconds in zone");
        session.Start(trial);var racer=Sample(36);racer.Position=new Vector3(850,0,0);session.Tick(racer,3,false);session.Tick(racer,15,false);
        Check(session.ObjectiveIndex==0 && session.Progress==0,"speed before reaching trial start does not count");
        racer.Position=trial.Objectives[0].point;session.Tick(racer,.1f,false);Check(session.ObjectiveIndex==1,"trial start activates speed objective");
        racer.Position=new Vector3(850,0,0);racer.SpeedKmh=18;session.Tick(racer,5,false);Check(session.Progress==5,"exact target speed advances trial hold");
        float elapsed=session.Elapsed;session.Tick(racer,20,true);Check(session.Progress==5 && session.Elapsed==elapsed,"pause preserves speed hold without advancing time");
        racer.SpeedKmh=17.9f;session.Tick(racer,.02f,false);Check(session.Progress==0,"speed dip resets continuous trial hold");
        racer.SpeedKmh=20;session.Tick(racer,4,false);racer.Position.x=861;session.Tick(racer,.02f,false);Check(session.Progress==0,"leaving side of speed zone resets hold");
        racer.Position=new Vector3(850,0,401);session.Tick(racer,4,false);Check(session.Progress==0,"speed beyond highway trial end does not count");
        racer.Position=new Vector3(850,0,0);racer.Grounded=false;session.Tick(racer,12,false);Check(session.Progress==0,"airborne speed cannot complete trial");
        racer.Grounded=true;session.Tick(racer,10,false);Check(session.State==MissionState.Completed,"continuous grounded speed inside zone completes trial");
        var trialCareer=new MissionCareer();Check(trialCareer.Record(5,1,session.Elapsed,trial.Reward) && !trialCareer.Record(5,1,session.Elapsed,trial.Reward) && trialCareer.points==150,"speed trial grants tier reward once");
        var nextTrial=MissionCatalog.Create(5,2);Check(nextTrial.Objectives[1].speedKmh==18.5f && nextTrial.Objectives[1].target==12 && nextTrial.TimeLimit<trial.TimeLimit,"next speed trial increases speed duration and time pressure");
        var topTrial=MissionCatalog.Create(5,100);Check(topTrial.Objectives[1].speedKmh==28 && topTrial.Objectives[1].target==35 && topTrial.TimeLimit==65,"speed trial upper difficulty remains bicycle feasible");
        foreach(var bicycle in GarageProgress.Catalog)Check(bicycle.Speed*3.6f>topTrial.Objectives[1].speedKmh,"every stock bicycle can exceed maximum trial target: "+bicycle.Name);
        var invalidZone=MissionCatalog.Create(5,1);invalidZone.Objectives[1].zoneSize=Vector3.zero;Check(!session.Start(invalidZone),"invalid speed trial bounds rejected");
        session.Start(trial);trial.Objectives[1].zoneSize=Vector3.one;Check(session.Definition.Objectives[1].zoneSize.x==20,"running speed zone is snapshotted from catalog");session.Fail("Crash");
        session.Start(MissionCatalog.Create(5,1));Check(session.ObjectiveIndex==0 && session.Progress==0,"speed trial retry restarts at entry with cleared hold");session.Abandon();
        var sprint=MissionCatalog.Create(6,1);var sprintMax=MissionCatalog.Create(6,100);
        Check(sprint.Id=="rival_sprint" && sprint.Objectives[0].target==300 && sprint.Objectives[0].speedKmh==18,"rival sprint starts with a 300m eighteen kmh rival");
        Check(MissionCatalog.Create(6,2).Objectives[0].target==315 && MissionCatalog.Create(6,2).Objectives[0].speedKmh>18 && sprintMax.Objectives[0].target==600 && sprintMax.Objectives[0].speedKmh==28.8f,"rival repeat difficulty increases and remains within highway");
        var oldSix=MissionCareer.FromJson("{\"version\":1,\"points\":900,\"completed\":[1,2,3,4,5,6]}");
        Check(oldSix.completed.Length==MissionCatalog.Count && oldSix.completed[5]==6 && oldSix.completed[6]==0 && oldSix.points==900,"rival append preserves all six existing career tiers");
        var rs=new MissionSample {Position=sprint.Objectives[0].point,Grounded=true};
        session.Start(sprint);session.Tick(rs,2,false);Check(session.RivalDistance==0,"rival stays on grid during countdown");
        session.Tick(rs,1,false);session.Tick(rs,2,false);Check(session.RivalDistance==4,"rival accelerates from rest at two meters per second squared");
        session.Tick(rs,5,true);Check(session.Elapsed==2 && session.RivalDistance==4,"pause freezes player and rival race clock");
        session.Tick(rs,3,false);Check(Mathf.Abs(session.RivalDistance-18.75f)<.001f,"rival reaches capped cruising speed");
        rs.Position.z+=300;session.Tick(rs,35,false);Check(session.State==MissionState.Completed && session.Result.Contains("1st") && session.Elapsed==40,"player finish ahead of rival wins");
        int events=completed;session.Tick(rs,100,false);Check(completed==events,"race reward event cannot repeat");
        rs.Position=sprint.Objectives[0].point;session.Start(sprint);session.Tick(rs,3,false);session.Tick(rs,70,false);
        Check(session.State==MissionState.Failed && Mathf.Abs(session.Elapsed-61.25f)<.001f && session.Result.Contains("2nd"),"stationary rider loses at exact rival finish time");
        session.Start(sprint);session.Tick(rs,3,false);rs.Position.z+=310;session.Tick(rs,70,false);
        Check(session.State==MissionState.Failed,"same tick crossings honor rival finishing before player");
        rs.Position=sprint.Objectives[0].point;session.Start(sprint);session.Tick(rs,3,false);rs.Position.z+=300;session.Tick(rs,61.25f,false);
        Check(session.State==MissionState.Completed,"exact race tie favors player");
        rs.Position=sprint.Objectives[0].point;session.Start(sprint);session.Tick(rs,3,false);rs.Position.x+=11;session.Tick(rs,.02f,false);
        Check(session.State==MissionState.Failed && session.Result.Contains("course"),"off course shortcut ends race");
        session.Start(sprint);Check(session.RivalDistance==0 && session.Progress==0,"retry resets both race distances");session.Abandon();
        var invalidRace=MissionCatalog.Create(6,1);invalidRace.Objectives[0].speedKmh=0;Check(!session.Start(invalidRace),"stationary rival definition rejected");
        foreach(var bicycle in GarageProgress.Catalog)Check(bicycle.Speed*3.6f>sprintMax.Objectives[0].speedKmh,"stock bicycle can beat maximum rival speed: "+bicycle.Name);
