        session.Start(firstWheelie);session.Tick(wheelie,2,false);Check(session.Progress==0,"first wheelie countdown excludes hold time");session.Tick(wheelie,1,false);
        session.Tick(wheelie,6,false);session.Tick(wheelie,10,true);Check(session.Progress==6 && session.Elapsed==6,"pause freezes first wheelie hold and deadline");
        session.Tick(Sample(),.02f,false);Check(session.Progress==0 && session.WheelieHoldBroken,"touchdown resets first wheelie and exposes reset guidance");
        session.Tick(Sample(),1,false);Check(session.WheelieHoldBroken,"reset guidance persists until next wheelie");
        session.Tick(wheelie,4,false);Check(session.Progress==4 && !session.WheelieHoldBroken && session.State==MissionState.Running,"separate wheelies do not combine toward target");
        session.Tick(wheelie,6,false);Check(session.State==MissionState.Completed,"one continuous ten second wheelie completes career mission");
        var wheelieCareer=new MissionCareer();Check(wheelieCareer.Record(7,1,session.Elapsed,firstWheelie.Reward) && !wheelieCareer.Record(7,1,session.Elapsed,firstWheelie.Reward) && wheelieCareer.points==150 && wheelieCareer.NextLevel(7)==2,"first wheelie rewards once and unlocks next tier");
        session.Start(firstWheelie);session.Tick(wheelie,3,false);session.Tick(wheelie,2,false);session.Tick(Sample(),.02f,false);session.Abandon();session.Start(firstWheelie);
        Check(session.Progress==0 && !session.WheelieHoldBroken,"retry clears interrupted hold guidance and duration");
